*** Add File: /app/drizzle-orm/src/sql/functions/window.ts
+import type { AnyColumn, GetColumnData } from '~/column.ts';
+import type { SQL, SQLWrapper } from '../sql.ts';
+import { sql } from '../sql.ts';
+
+type WindowExpression = SQLWrapper;
+type WindowValue<T extends WindowExpression> = T extends AnyColumn ? GetColumnData<T> : T extends SQL<infer TValue> ? TValue : unknown;
+
+export type WindowFrameBoundary =
+	| typeof unboundedPreceding
+	| typeof currentRow
+	| typeof unboundedFollowing
+	| PrecedingBoundary
+	| FollowingBoundary;
+
+export interface WindowFrame {
+	readonly type: 'rows' | 'range';
+	readonly from: WindowFrameBoundary;
+	readonly to: WindowFrameBoundary;
+}
+
+export interface WindowSpec {
+	partitionBy?: WindowExpression | WindowExpression[];
+	orderBy?: WindowExpression | WindowExpression[];
+	frame?: WindowFrame;
+}
+
+class FrameBoundary implements SQLWrapper {
+	constructor(readonly sqlText: string, readonly position: number) {}
+	getSQL(): SQL { return sql.raw(this.sqlText); }
+}
+
+class PrecedingBoundary extends FrameBoundary {}
+class FollowingBoundary extends FrameBoundary {}
+
+/** A frame boundary representing the first row in a partition. */
+export const unboundedPreceding = new FrameBoundary('unbounded preceding', Number.NEGATIVE_INFINITY);
+/** A frame boundary representing the current row. */
+export const currentRow = new FrameBoundary('current row', 0);
+/** A frame boundary representing the last row in a partition. */
+export const unboundedFollowing = new FrameBoundary('unbounded following', Number.POSITIVE_INFINITY);
+
+function validateOffset(name: string, value: number): void {
+	if (!Number.isInteger(value) || value < 0) {
+		throw new Error(`${name}() expects a non-negative integer; received ${value}`);
+	}
+}
+
+/** Creates an N PRECEDING frame boundary. */
+export function preceding(value: number): WindowFrameBoundary {
+	validateOffset('preceding', value);
+	return new PrecedingBoundary(`${value} preceding`, -value);
+}
+
+/** Creates an N FOLLOWING frame boundary. */
+export function following(value: number): WindowFrameBoundary {
+	validateOffset('following', value);
+	return new FollowingBoundary(`${value} following`, value);
+}
+
+function frame(type: WindowFrame['type'], spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	if (spec.from.position > spec.to.position) {
+		throw new Error('Window frame "from" boundary must not be after its "to" boundary');
+	}
+	return { type, ...spec };
+}
+
+/** Creates a ROWS window frame. */
+export function rows(spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	return frame('rows', spec);
+}
+
+/** Creates a RANGE window frame. */
+export function range(spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	return frame('range', spec);
+}
+
+export function buildWindowSpec(spec: WindowSpec): SQL {
+	const chunks: SQL[] = [];
+	const partitionBy = spec.partitionBy === undefined ? [] : (Array.isArray(spec.partitionBy) ? spec.partitionBy : [spec.partitionBy]);
+	const orderBy = spec.orderBy === undefined ? [] : (Array.isArray(spec.orderBy) ? spec.orderBy : [spec.orderBy]);
+	if (partitionBy.length) chunks.push(sql`partition by ${sql.join(partitionBy, sql`, `)}`);
+	if (orderBy.length) chunks.push(sql`order by ${sql.join(orderBy, sql`, `)}`);
+	if (spec.frame) chunks.push(sql`${sql.raw(spec.frame.type)} between ${spec.frame.from} and ${spec.frame.to}`);
+	return sql.join(chunks, sql` `);
+}
+
+/** A SQL window function awaiting its OVER clause. */
+export class WindowFunctionBuilder<T> {
+	constructor(private readonly expression: SQL<T>) {}
+
+	over(spec: WindowSpec | string = {}): SQL<T> {
+		if (typeof spec === 'string') return sql`${this.expression} over ${sql.identifier(spec)}`;
+		return sql`${this.expression} over (${buildWindowSpec(spec)})`;
+	}
+}
+
+function windowFunction<T>(name: string, args: SQLWrapper[] = []): WindowFunctionBuilder<T> {
+	return new WindowFunctionBuilder(sql`${sql.raw(name)}(${sql.join(args, sql`, `)})`);
+}
+
+function positionalArgument(name: string, value: number): SQL {
+	if (!Number.isInteger(value) || value <= 0) throw new Error(`${name}() expects a positive integer; received ${value}`);
+	return sql.raw(String(value));
+}
+
+export function rowNumber(): WindowFunctionBuilder<number> { return windowFunction('row_number'); }
+export function rank(): WindowFunctionBuilder<number> { return windowFunction('rank'); }
+export function denseRank(): WindowFunctionBuilder<number> { return windowFunction('dense_rank'); }
+export function ntile(buckets: number): WindowFunctionBuilder<number> { return windowFunction('ntile', [positionalArgument('ntile', buckets)]); }
+export function percentRank(): WindowFunctionBuilder<number> { return windowFunction('percent_rank'); }
+export function cumeDist(): WindowFunctionBuilder<number> { return windowFunction('cume_dist'); }
+
+export function lag<T extends WindowExpression>(value: T, offset?: number): WindowFunctionBuilder<WindowValue<T> | null>;
+export function lag<T extends WindowExpression>(value: T, offset: number | undefined, defaultValue: unknown): WindowFunctionBuilder<NonNullable<WindowValue<T>>>;
+export function lag<T extends WindowExpression>(value: T, offset?: number, defaultValue?: unknown): WindowFunctionBuilder<WindowValue<T> | null> {
+	const args: SQLWrapper[] = [value];
+	if (offset !== undefined) args.push(sql.raw(String(offset)));
+	if (defaultValue !== undefined) args.push(defaultValue as SQLWrapper);
+	return windowFunction('lag', args);
+}
+
+export function lead<T extends WindowExpression>(value: T, offset?: number): WindowFunctionBuilder<WindowValue<T> | null>;
+export function lead<T extends WindowExpression>(value: T, offset: number | undefined, defaultValue: unknown): WindowFunctionBuilder<NonNullable<WindowValue<T>>>;
+export function lead<T extends WindowExpression>(value: T, offset?: number, defaultValue?: unknown): WindowFunctionBuilder<WindowValue<T> | null> {
+	const args: SQLWrapper[] = [value];
+	if (offset !== undefined) args.push(sql.raw(String(offset)));
+	if (defaultValue !== undefined) args.push(defaultValue as SQLWrapper);
+	return windowFunction('lead', args);
+}
+
+export function firstValue<T extends WindowExpression>(value: T): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('first_value', [value]); }
+export function lastValue<T extends WindowExpression>(value: T): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('last_value', [value]); }
+export function nthValue<T extends WindowExpression>(value: T, nth: number): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('nth_value', [value, positionalArgument('nthValue', nth)]); }
+
+export function windowSum<T extends WindowExpression>(value: T): WindowFunctionBuilder<string | null> { return windowFunction('sum', [value]); }
+export function windowAvg<T extends WindowExpression>(value: T): WindowFunctionBuilder<string | null> { return windowFunction('avg', [value]); }
+export function windowMin<T extends WindowExpression>(value: T): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('min', [value]); }
+export function windowMax<T extends WindowExpression>(value: T): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('max', [value]); }
+export function windowCount(value?: WindowExpression): WindowFunctionBuilder<number> { return windowFunction('count', value ? [value] : [sql.raw('*')]); }
