+} from '~/index.ts';
+import { PgDialect, pgTable, serial } from '~/pg-core/index.ts';
+
+const users = pgTable('users', { id: serial().primaryKey() });
+const dialect = new PgDialect();
+
+function query(expression: { getSQL(): import('~/sql/sql.ts').SQL }) {
+	return dialect.sqlToQuery(expression.getSQL());
+}
+
+test('window functions compile and keep positional arguments inline', () => {
+	const spec = { partitionBy: users.id, orderBy: users.id, frame: rows({ from: preceding(0), to: currentRow }) };
+	expect(query(rowNumber().over(spec)).sql).toBe('row_number() over (partition by "users"."id" order by "users"."id" rows between 0 preceding and current row)');
+	expect(query(rank().over()).sql).toBe('rank() over ()');
+	expect(query(denseRank().over()).sql).toBe('dense_rank() over ()');
+	expect(query(ntile(2).over()).sql).toBe('ntile(2) over ()');
+	expect(query(percentRank().over()).sql).toBe('percent_rank() over ()');
+	expect(query(cumeDist().over()).sql).toBe('cume_dist() over ()');
+	expect(query(lag(users.id, 0).over()).sql).toBe('lag("users"."id", 0) over ()');
+	expect(query(lead(users.id, 0, 42).over()).params).toEqual([42]);
+	expect(query(nthValue(users.id, 1).over()).sql).toBe('nth_value("users"."id", 1) over ()');
+	expect(query(windowSum(users.id).over()).sql).toBe('sum("users"."id") over ()');
+	expect(query(windowAvg(users.id).over()).sql).toBe('avg("users"."id") over ()');
+	expect(query(windowMin(users.id).over()).sql).toBe('min("users"."id") over ()');
+	expect(query(windowMax(users.id).over()).sql).toBe('max("users"."id") over ()');
+	expect(query(windowCount().over()).sql).toBe('count(*) over ()');
+});
+
+test('window definitions are quoted and emitted before order by', () => {
+	const sql = dialect.sqlToQuery(dialect.buildSelectQuery({
+		fields: { id: users.id },
+		table: users,
+		setOperators: [],
+		windows: [{ name: 'rank window', spec: { orderBy: users.id, frame: range({ from: unboundedPreceding, to: following(1) }) } }],
+		orderBy: [users.id],
+	})).sql;
+	expect(sql).toBe('select "id" from "users" window "rank window" as (order by "users"."id" range between unbounded preceding and 1 following) order by "users"."id"');
